  // lib/leaderboard-breakdown.js
  "Unknown source": "Неизвестный источник",
  "Source": "Источник",
  "No chests in this timeframe.": "Нет сундуков за этот период.",
  "{n} points": { one: "{n} очко", few: "{n} очка", many: "{n} очков", other: "{n} очков" },
  "Loading…": "Загрузка…",
