  "Cannot merge a source with itself": "Нельзя объединить источник с самим собой",
  "Triumphal Chest Points": "Очки триумфальных сундуков",
  "One <strong>global scoring table</strong> for the <strong>Bank Gifts</strong> tab, tracked separately from the main leaderboard. Each value is the <strong>package price</strong> (a full 3-of-a-kind set); a single chest is worth one third of it, rounded — so three of a kind sum back to exactly the package value. Rows tagged {new} have been seen in scans but have <strong>no value yet</strong> (they score 0) — set a value to score them.": "Одна <strong>общая таблица очков</strong> для вкладки <strong>Банковские подарки</strong>, учитывается отдельно от основного рейтинга. Каждое значение — <strong>цена набора</strong> (полный комплект из трёх одинаковых); один сундук стоит треть от неё с округлением — так три одинаковых в сумме дают ровно цену набора. Строки с меткой {new} встречались при сканировании, но <strong>ещё не имеют значения</strong> (дают 0) — задайте значение, чтобы они учитывались.",
  "New": "Новый",
  "Managed here by superadmins; values apply to every clan.": "Управляется здесь суперадминами; значения действуют для всех кланов.",
  "<strong>Read-only</strong> — only a superadmin can change these values.": "<strong>Только чтение</strong> — менять эти значения может только суперадмин.",
  "Show triumphal chest values ({count})": "Показать стоимость триумфальных сундуков ({count})",
  "Chests Seen": "Встречено сундуков",
  "Per Chest": "За сундук",
  "Package (3-of-a-kind)": "Набор (3 одинаковых)",
  "Seen in scans but has no point value yet — it currently scores 0. Set a package value to score it.": "Встречался при сканировании, но ещё не имеет стоимости — сейчас даёт 0. Задайте цену набора, чтобы он учитывался.",
  "{n} seen": { one: "встречен {n} раз", few: "встречен {n} раза", many: "встречен {n} раз", other: "встречен {n} раза" },
  "Save All Changes": "Сохранить все изменения",
  "Saves every chest whose package value changed. Clear an input to remove that chest's value — it reverts to \"new\" and scores 0 until set again. Points are presentation-only, so no historical backfill is needed.": "Сохраняет все сундуки, у которых изменилась цена набора. Очистите поле, чтобы убрать значение сундука — он вернётся в статус \"новый\" и будет давать 0, пока значение не задано снова. Очки влияют только на отображение, поэтому пересчёт истории не нужен.",
  "No triumphal chest data yet.": "Данных о триумфальных сундуках пока нет.",
  "\"{chest}\" must be a non-negative integer": "\"{chest}\" должно быть неотрицательным целым числом",
  "No changes to save.": "Нет изменений для сохранения.",
  "Nothing to do": "Нечего делать",
  "Some changes failed:\n{errors}": "Некоторые изменения не сохранились:\n{errors}",
  "Partial save": "Частичное сохранение",
