  "Saved": "Сохранено",
  "Review Queue": "Очередь проверки",
  "{n} new": { one: "{n} новый", few: "{n} новых", many: "{n} новых", other: "{n} новых" },
  "New Triumphal Chests": "Новые триумфальные сундуки",
  "Chest Name": "Название сундука",
  "First Seen": "Впервые",
  "Assign each a package value under {link} on the Points tab — that scores them and clears them from this list.": "Задайте каждому цену набора в разделе {link} на вкладке «Очки» — это начислит очки и уберёт их из этого списка.",
  "Delete this merge rule? Existing records that were already rewritten by this rule are not reverted, but future scans will stop auto-applying it.": "Удалить это правило объединения? Записи, уже переписанные этим правилом, не вернутся, но будущие сканирования перестанут его применять.",
