  // pages/clan-chat-digest.js
  "In-game chat digest": "Сводка в игровом чате",
  "Could not load the chat digest settings.": "Не удалось загрузить настройки сводки в чате.",
  "Today's message has gone out.": "Сегодняшнее сообщение отправлено.",
  "Today's message may already have gone out, so it is never sent again.": "Сегодняшнее сообщение, возможно, уже отправлено, поэтому повторно не отправляется.",
  "Posting failed twice for this day; it is not tried again.": "Отправка за этот день дважды не удалась; больше попыток не будет.",
  "A message already went out today (the {date} digest).": "Сегодня уже ушло сообщение (сводка за {date}).",
  "Waiting for the day's closing scan.": "Ждём скан, закрывающий день.",
  "Not posting: there was no scan before the day began, so it may be incomplete.": "Не отправляем: до начала дня не было скана, данные могут быть неполными.",
  "Not posting: a {hours} h gap between scans that day, so it may be incomplete.": "Не отправляем: в тот день между сканами был перерыв {hours} ч, данные могут быть неполными.",
  "Posted": "Отправлено",
  "Failed": "Ошибка",
  "Unknown — not resent": "Неизвестно — повторно не отправляется",
  "Sending": "Отправка",
  "Chat sending is switched off on this server.": "Отправка в чат на этом сервере отключена.",
  "Pick a group chat the scanner account is in first.": "Сначала выберите групповой чат, в котором состоит аккаунт сканера.",
  "Nothing was collected that day.": "В тот день ничего не собрано.",
  "Posts the daily digest into one of the clan's in-game group chats, as the clan's scanner account: the same “Daily Digest — Our top 20 crypters” message the leaders post by hand. <strong>At most one message a day</strong>, never split, never into the clan chat, the kingdom chat or a private chat.": "Публикует ежедневную сводку в один из групповых чатов клана в игре от имени аккаунта сканера клана — то же сообщение «Daily Digest — Our top 20 crypters», которое руководство публикует вручную. <strong>Не больше одного сообщения в день</strong>, никогда не по частям, никогда в клановый чат, чат королевства или личные сообщения.",
  "Chat sending is switched off on this server (CHAT_SEND_DISABLED): nothing is posted.": "Отправка в чат на этом сервере отключена (CHAT_SEND_DISABLED): ничего не публикуется.",
  "Posts as <strong>{name}</strong>, the account that scans this clan.": "Публикует <strong>{name}</strong> — аккаунт, который сканирует этот клан.",
