  "Sunday to Sunday (7 days)": "С воскресенья по воскресенье (7 дней)",
  "In a Seasonal Kingdom, Tinman to Tinman opens when {event} ({ancients} day 2) begins at 17:00 UTC and runs until the next one begins, {n} days later.": { one: "В Сезонном королевстве неделя от Tin Man до Tin Man начинается, когда {event} (день 2 {ancients}) стартует в 17:00 UTC, и длится до следующего старта через {n} день.", few: "В Сезонном королевстве неделя от Tin Man до Tin Man начинается, когда {event} (день 2 {ancients}) стартует в 17:00 UTC, и длится до следующего старта через {n} дня.", many: "В Сезонном королевстве неделя от Tin Man до Tin Man начинается, когда {event} (день 2 {ancients}) стартует в 17:00 UTC, и длится до следующего старта через {n} дней.", other: "В Сезонном королевстве неделя от Tin Man до Tin Man начинается, когда {event} (день 2 {ancients}) стартует в 17:00 UTC, и длится до следующего старта через {n} дня." },
  "Tinman to Tinman opens when {event} ({ancients} day 2) begins at 17:00 UTC and runs until the next one begins, six days later.": "Неделя от Tin Man до Tin Man начинается, когда {event} (день 2 {ancients}) стартует в 17:00 UTC, и длится до следующего старта через шесть дней.",
