  "Disable this share link? The URL stops working immediately and the clan’s other links are unaffected. It keeps its history and can be restored later from “Analytics & history”.": "Отключить эту ссылку для просмотра? URL сразу перестанет работать, другие ссылки клана не затронуты. История ссылки сохраняется, её можно восстановить позже в «Аналитика и история».",
