  "✓ Copied!": "✓ Скопировано!",
  "Click to copy": "Нажмите, чтобы скопировать",
  "Delete clan \"{clan}\"? It disappears from the clan picker, the scanner, Discord and its public share link, and its members can no longer sign in to it.\n\nIts data — members, scans, chests, resources, settings — is KEPT, and a superadmin can put the clan back from System → Deleted Clans.": "Удалить клан \"{clan}\"? Он исчезнет из выбора кланов, сканера, Discord и публичной ссылки для просмотра, а его участники больше не смогут в него войти.\n\nЕго данные — участники, сканирования, сундуки, ресурсы, настройки — СОХРАНЯЮТСЯ, и суперадмин может вернуть клан в «Система → Удалённые кланы».",
  "Delete clan \"{clan}\"": "Удалить клан \"{clan}\"",
