  "Not authenticated": "Вход не выполнен",
  "The last scan or login check found this clan's saved Total Battle session signed out — it has likely expired. Re-authenticate below to resume scans.": "Последнее сканирование или проверка входа обнаружили, что сохранённый сеанс Total Battle этого клана вышел из системы — вероятно, он истёк. Войдите заново ниже, чтобы возобновить сканирование.",
  "A previous login was saved for this clan. If scans fail with auth errors, refresh the session below.": "Для этого клана сохранён предыдущий вход. Если сканирования падают с ошибками авторизации, обновите сеанс ниже.",
