  "{n} servers — pick one to load its channels.": { one: "{n} сервер — выберите его, чтобы загрузить каналы.", few: "{n} сервера — выберите один, чтобы загрузить его каналы.", many: "{n} серверов — выберите один, чтобы загрузить его каналы.", other: "{n} сервера — выберите один, чтобы загрузить его каналы." },
