  // pages/dashboard.js
  "Total Chests": "Всего сундуков",
  "Clan Members": "Участники клана",
  "Total Scans": "Всего сканирований",
  "Avg Chests/Scan": "Сред. сундуков/скан",
  "Last Scan": "Последний скан",
  "Weekly Top Contributors": "Лучшие за неделю",
  "No data yet.": "Данных пока нет.",
  "Recent Chests": "Последние сундуки",
  "No chests yet.": "Сундуков пока нет.",
  "Clan Records — Best Single Day": "Рекорды клана — лучший день",
  "All-time personal best days across the whole clan. Each member only appears once per podium (their own record day). Excludes end-of-event clan rewards — the placement prize the game drops on one account for the whole clan.": "Личные рекордные дни за всё время по всему клану. Каждый участник появляется на пьедестале один раз (свой рекордный день). Без клановых наград за итог события — приза за место, который игра выдаёт одному аккаунту за весь клан.",
  "Most Chests in a Day": "Больше всего сундуков за день",
