  "Aggregate across all occurrences": "Сумма по всем запускам",
  "The latest run is level with the one before it, and is still in progress.": "Последний запуск на уровне предыдущего и ещё идёт.",
  "The latest run is level with the one before it.": "Последний запуск на уровне предыдущего.",
