  "this clan": "этот клан",
  "What each chest source is worth for <strong>{clan}</strong> — every clan has its own values; switch clan to edit another clan's.": "Сколько стоит каждый источник сундуков для <strong>{clan}</strong> — у каждого клана свои значения; переключите клан, чтобы изменить значения другого.",
  "What each chest source is worth for <strong>{clan}</strong> — every clan has its own values.": "Сколько стоит каждый источник сундуков для <strong>{clan}</strong> — у каждого клана свои значения.",
  "Most sources pay one value for every chest they drop; the few that pay some chests differently list those under the source.": "Большинство источников дают одно значение за каждый выпавший сундук; немногие, где некоторые сундуки стоят иначе, перечисляют их под источником.",
  "When you save, you choose: from today on (chests from earlier days keep their points) or for all history (every recorded chest is rescored — for fixing a wrong value).": "При сохранении вы выбираете: с сегодняшнего дня (сундуки прошлых дней сохраняют свои очки) или для всей истории (каждый записанный сундук пересчитывается — чтобы исправить ошибочное значение).",
