  "chest records change": { one: "запись сундука изменится", few: "записи сундуков изменятся", many: "записей сундуков изменятся", other: "записей сундуков изменятся" },
  "points in total": { one: "очко всего", few: "очка всего", many: "очков всего", other: "очков всего" },
  "Chests of <strong>{clan}</strong> already recorded today are rescored; everything before today keeps its points.": "Сундуки клана <strong>{clan}</strong>, уже записанные сегодня, пересчитываются; всё до сегодняшнего дня сохраняет свои очки.",
  "No chest recorded before now changes — chests of <strong>{clan}</strong> from today on score the new values.": "Уже записанные сундуки не меняются — сундуки клана <strong>{clan}</strong> с сегодняшнего дня получают новые значения.",
  "This joins the change already saved for today, {day}.": "Это добавится к изменению, уже сохранённому на сегодня ({day}).",
  "Every stored chest record of <strong>{clan}</strong> from these sources gets the new value, whatever day it was earned.": "Каждая сохранённая запись сундука клана <strong>{clan}</strong> из этих источников получает новое значение, в какой бы день она ни была получена.",
