  "Save {n} changes for {clan}?": { one: "Сохранить {n} изменение для {clan}?", few: "Сохранить {n} изменения для {clan}?", many: "Сохранить {n} изменений для {clan}?", other: "Сохранить {n} изменений для {clan}?" },
