  "From today on": "С сегодняшнего дня",
  "Chests from game day {day} on score the new values. Chests from earlier days keep their points.": "Сундуки с игрового дня {day} получают новые значения. Сундуки прошлых дней сохраняют свои очки.",
  "All history": "Вся история",
  "Every chest this clan ever recorded is rescored. Use it to fix a value that was wrong.": "Пересчитывается каждый сундук, когда-либо записанный этим кланом. Используйте, чтобы исправить ошибочное значение.",
