  "Chest points saved": "Очки сундуков сохранены",
  "You have {n} unsaved changes. Recalculate only uses saved values — use Review & save first (saving updates the stored records itself).": { one: "У вас {n} несохранённое изменение. «Пересчитать» использует только сохранённые значения — сначала нажмите «Проверить и сохранить» (сохранение само обновляет сохранённые записи).", few: "У вас {n} несохранённых изменения. «Пересчитать» использует только сохранённые значения — сначала нажмите «Проверить и сохранить» (сохранение само обновляет сохранённые записи).", many: "У вас {n} несохранённых изменений. «Пересчитать» использует только сохранённые значения — сначала нажмите «Проверить и сохранить» (сохранение само обновляет сохранённые записи).", other: "У вас {n} несохранённых изменений. «Пересчитать» использует только сохранённые значения — сначала нажмите «Проверить и сохранить» (сохранение само обновляет сохранённые записи)." },
  "Save your changes first": "Сначала сохраните изменения",
  "Recalculate failed": "Не удалось пересчитать",
  "Every stored chest record already matches the current values — saves update records as they are made.": "Все сохранённые записи сундуков уже соответствуют текущим значениям — при сохранении записи обновляются сразу.",
  "Nothing to recalculate": "Нечего пересчитывать",
  "Recalculate chest points?": "Пересчитать очки сундуков?",
  "These stored records of <strong>{clan}</strong> no longer match the values in force on the day they were earned (usually chests scanned before a value was set). Recalculating brings them in line.": "Эти сохранённые записи клана <strong>{clan}</strong> больше не совпадают со значениями, действовавшими в день их получения (обычно это сундуки, отсканированные до того, как было задано значение). Пересчёт приводит их в соответствие.",
  "Recalculated": "Пересчитано",
  "You have {n} unsaved changes. Copying replaces every value, so save or discard them first.": { one: "У вас {n} несохранённое изменение. Копирование заменяет все значения, поэтому сначала сохраните или отмените его.", few: "У вас {n} несохранённых изменения. Копирование заменяет все значения, поэтому сначала сохраните или отмените их.", many: "У вас {n} несохранённых изменений. Копирование заменяет все значения, поэтому сначала сохраните или отмените их.", other: "У вас {n} несохранённых изменений. Копирование заменяет все значения, поэтому сначала сохраните или отмените их." },
  "There is no other clan to copy values from.": "Нет другого клана, из которого можно скопировать значения.",
  "Nothing to copy": "Нечего копировать",
  "Every chest point value of {clan} is replaced by the other clan's. The other clan is not changed.": "Все значения очков сундуков клана {clan} будут заменены значениями другого клана. Другой клан не изменится.",
  "Copy values into {clan}": "Скопировать значения в {clan}",
  "Copy from": "Копировать из",
  "Copy {from}'s values into {clan}?": "Скопировать значения {from} в {clan}?",
  "<strong>{clan}</strong> will pay exactly what <strong>{from}</strong> pays ({n} saved values; anything {from} hasn't set uses the built-in default).": { one: "<strong>{clan}</strong> будет давать ровно столько же, сколько <strong>{from}</strong> ({n} сохранённое значение; всё, что {from} не задал, использует встроенное значение по умолчанию).", few: "<strong>{clan}</strong> будет давать ровно столько же, сколько <strong>{from}</strong> ({n} сохранённых значения; всё, что {from} не задал, использует встроенное значение по умолчанию).", many: "<strong>{clan}</strong> будет давать ровно столько же, сколько <strong>{from}</strong> ({n} сохранённых значений; всё, что {from} не задал, использует встроенное значение по умолчанию).", other: "<strong>{clan}</strong> будет давать ровно столько же, сколько <strong>{from}</strong> ({n} сохранённых значений; всё, что {from} не задал, использует встроенное значение по умолчанию)." },
  "These stored chest records of {clan} are updated right away. {from} is not changed.": "Эти сохранённые записи сундуков клана {clan} обновятся сразу. {from} не изменится.",
  "No stored chest record of {clan} changes. {from} is not changed.": "Сохранённые записи сундуков клана {clan} не изменятся. {from} не изменится.",
  "The copied values apply to all history, so the {n} dated changes of {clan} go.": { one: "Скопированные значения действуют для всей истории, поэтому изменение с датой клана {clan} удаляется.", few: "Скопированные значения действуют для всей истории, поэтому {n} изменения с датой клана {clan} удаляются.", many: "Скопированные значения действуют для всей истории, поэтому {n} изменений с датой клана {clan} удаляются.", other: "Скопированные значения действуют для всей истории, поэтому {n} изменений с датой клана {clan} удаляются." },
