  "{n} members donated {resource} between {from} and {to}.": { one: "{n} участник пожертвовал ресурс «{resource}» с {from} по {to}.", few: "{n} участника пожертвовали ресурс «{resource}» с {from} по {to}.", many: "{n} участников пожертвовали ресурс «{resource}» с {from} по {to}.", other: "{n} участника пожертвовали ресурс «{resource}» с {from} по {to}." },
  "Nothing pasted for this run yet — an admin adds the ranking on {link} after each day.": "Для этого проведения пока ничего не вставлено — админ добавляет рейтинг в разделе {link} после каждого дня.",
