  "<strong>{n}</strong> players share": { one: "<strong>{n}</strong> игрок в разделе", few: "<strong>{n}</strong> игрока в разделе", many: "<strong>{n}</strong> игроков в разделе", other: "<strong>{n}</strong> игрока в разделе" },
  "<strong>{n}</strong> left out": { one: "<strong>{n}</strong> исключён", few: "<strong>{n}</strong> исключено", many: "<strong>{n}</strong> исключено", other: "<strong>{n}</strong> исключено" },
  "{column} total <strong>{total}</strong>": "{column}, всего <strong>{total}</strong>",
  "Enter the clan's totals above to see what each player gets.": "Введите итоги клана выше, чтобы увидеть, сколько получит каждый игрок.",
  "No player matches “{query}”.": "Нет игроков по запросу «{query}».",
  "No longer on the clan roster — a reward can't reach them. Tick to include anyway.": "Больше нет в списке клана — награду отправить нельзя. Отметьте, чтобы всё равно включить.",
  "left the clan": "покинул клан",
  "Not matched to a clan member yet": "Ещё не сопоставлен с участником клана",
  "not matched": "не сопоставлен",
  "{n} fragments": { one: "{n} фрагмент", few: "{n} фрагмента", many: "{n} фрагментов", other: "{n} фрагмента" },
  "Leave out {name}": "Исключить {name}",
  "Include {name}": "Включить {name}",
  "Included": "Включён",
  "<strong>The split.</strong> Each player gets the pot × their score ÷ everyone's total, rounded down. The units left over go one each to the largest remainders, so the parts always add up to the pot.": "<strong>Раздел.</strong> Каждый игрок получает банк × свои очки ÷ сумму очков всех, с округлением вниз. Оставшиеся единицы идут по одной к наибольшим остаткам, так что доли всегда в сумме дают весь банк.",
  "<strong>Leaving someone out.</strong> Untick them: they get nothing, and their part is spread over everyone else by score. Who you leave out is remembered in this browser.": "<strong>Исключение.</strong> Снимите отметку: игрок ничего не получит, а его доля распределится между остальными по очкам. Исключения запоминаются в этом браузере.",
  "<strong>Left the clan.</strong> Players the roster no longer lists start unticked — a reward can only be sent to a member.": "<strong>Покинувшие клан.</strong> Игроки, которых больше нет в списке клана, изначально не отмечены — награду можно отправить только участнику.",
  "<strong>{olympus}.</strong> The clan ranking pasted on Events → {olympus}, as it stood after the day you pick. The ranking keeps growing through the run, so the last day is the whole run.": "<strong>{olympus}.</strong> Рейтинг клана, вставленный в разделе События → {olympus}, на конец выбранного дня. Рейтинг растёт всё проведение, так что последний день — это всё проведение.",
  "<strong>{omens}.</strong> {essence} donated during the run, from resource tracking, or the {spoils} damage ranking pasted on Events → {omens}.": "<strong>{omens}.</strong> Ресурс «{essence}», пожертвованный за проведение (по учёту ресурсов), или рейтинг урона «{spoils}», вставленный в разделе События → {omens}.",
  "Splits like {link}. Where a leftover fragment could go either way, it may land on a different player.": "Делит как {link}. Если оставшийся фрагмент может достаться любому из двух, он может уйти другому игроку.",
  "totalcalculator.org's rewards page": "страница наград totalcalculator.org",
