  "{date} isn't a Tinman day on the Seasonal Kingdom calendar.": "{date} — не день Tin Man по календарю Сезонного королевства.",
  "{date} isn't a Tinman day on the usual 6-day cadence.": "{date} — не день Tin Man в обычном 6-дневном цикле.",
  "Totals are held against each tier's target for the whole run.": "Итоги сравниваются с целью каждого уровня за весь запуск.",
  "No targets for this run yet — open <strong>Targets</strong> and paste the <em>Points per member</em> table from {link}.": "Целей для этого запуска пока нет — откройте <strong>Цели</strong> и вставьте таблицу <em>Очки на участника</em> из {link}.",
  "Tools → Ancient planner": "Инструменты → Планировщик Древних",
