  "Points per member": "Очки на участника",
  "<strong>Vault pot.</strong> Each member raids one vault in {event}. Their guards level caps its size: G1 1,000 … G9 8,200 vault points.": "<strong>Котёл сокровищниц.</strong> Каждый участник совершает набег на одну сокровищницу в {event}. Её размер ограничен уровнем гвардейцев: G1 1 000 … G9 8 200 очков сокровищницы.",
  "<strong>What it buys.</strong> The Figurine (summons) and the Tome you pick come first. The Clock gets the rest, up to 120 minutes.": "<strong>На что тратится.</strong> Сначала Figurine (призывы) и выбранный Tome. Остальное идёт на Clock, до 120 минут.",
  "<strong>The target.</strong> Every summon is planned as a kill, one {tinman} level higher each time. The clan must score their combined HP plus the Tome bonus.": "<strong>Цель.</strong> Каждый призыв планируется как убийство, каждый раз на один уровень {tinman} выше. Клан должен набрать их суммарное HP плюс бонус Tome.",
  "<strong>The split.</strong> Each tier gets a fixed weight (G9 = 2.25× G8, and T9 = 1.75× G9). The ratios are a planning convention, not game data.": "<strong>Распределение.</strong> Каждый уровень получает фиксированный вес (G9 = 2,25× G8, а T9 = 1,75× G9). Эти соотношения — условность для планирования, а не данные игры.",
  "<strong>Summons 7 and 8</strong> are only offered while a seasonal kingdom runs.": "<strong>Призывы 7 и 8</strong> доступны только во время сезонного королевства.",
  "Matches {link}, rebuilt from its outputs.": "Совпадает с {link}, воссоздан по его результатам.",
