  "No triumphal chests in this period.": "Нет триумфальных сундуков за этот период.",
  "About triumphal chests": "О триумфальных сундуках",
  "Triumphal chests come from in-game package purchases. Each chest is worth one third of its package value, shown rounded to a whole number — Magic ≈83, Precious ≈33, Golden ≈17, Silver ≈7, Bronze ≈3, Wooden ≈2 — so a full set of three sums back to the package value (3 Golden = 50). These points are tracked separately from the main leaderboard.": "Триумфальные сундуки дают покупки наборов в игре. Каждый сундук стоит треть стоимости своего набора, округлённую до целого — Magic ≈83, Precious ≈33, Golden ≈17, Silver ≈7, Bronze ≈3, Wooden ≈2, — так что полный набор из трёх в сумме даёт стоимость набора (3 Golden = 50). Эти очки учитываются отдельно от основного рейтинга.",
